/**
 * Procedural block textures — the LCW "painted toy block" look (docs/08 1장 '따뜻한 장난감 블록', 6.1).
 *
 * Every pixel is generated by the code below from the docs/08 color tokens; no external or reference-game texture
 * is used or traced (AGENTS 4.11, docs/15). The style is deliberately unlike pixel-art voxel games:
 *  - 32 x 32 texels, linear filtering: shapes are soft and anti-aliased, not crisp noisy pixels.
 *  - each tile is a flat warm pastel with a gentle top-light gradient and ONE large simple motif
 *    (two wide boards, round pebbles, scale shingles, felt stitches) instead of speckle noise;
 *  - block edges get a rounded toy bevel in the shader (materials.ts), so every block reads as a painted toy cube;
 *  - signature props are LCW's own: honey-jar shelves, speech-bubble signs, felt wool, frosting-capped grass.
 */
import { TILE_NAMES, type TileName } from './blocks.js';

export const TILE_PX = 32;
const S = TILE_PX;

type RGB = readonly [number, number, number];

function hex(h: number): RGB {
  return [(h >> 16) & 255, (h >> 8) & 255, h & 255];
}

function mix(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function shade(c: RGB, k: number): RGB {
  return k >= 1 ? mix(c, [255, 255, 255], k - 1) : mix([0, 0, 0], c, k);
}

/** Integer hash in [0, 1). Deterministic per (seed, x, y). */
function hash2(seed: number, x: number, y: number): number {
  let h = (seed * 374761393 + x * 668265263 + y * 2147483647) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return ((h >>> 0) % 10007) / 10007;
}

interface Painter {
  /** blend color c over texel (x, y) with coverage a (0..1) */
  put(x: number, y: number, c: RGB, a?: number): void;
  /** vertical gradient, top color to bottom color */
  grad(top: RGB, bottom: RGB): void;
  circle(cx: number, cy: number, r: number, c: RGB, a?: number): void;
  ring(cx: number, cy: number, r: number, w: number, c: RGB, a?: number): void;
  rrect(x0: number, y0: number, x1: number, y1: number, r: number, c: RGB, a?: number): void;
  clear(): void;
}

function makePainter(buf: Uint8Array, base: number): Painter {
  const put = (x: number, y: number, c: RGB, a = 1): void => {
    if (x < 0 || y < 0 || x >= S || y >= S || a <= 0) return;
    // y = 0 is the top row of the tile (texture v = 1 in the shader).
    const i = base + ((S - 1 - y) * S + x) * 4;
    const k = Math.min(1, a);
    const da = buf[i + 3]! / 255;
    const oa = k + da * (1 - k);
    for (let ch = 0; ch < 3; ch++) {
      const dst = buf[i + ch]!;
      buf[i + ch] = Math.round(oa > 0 ? (c[ch]! * k + dst * da * (1 - k)) / oa : 0);
    }
    buf[i + 3] = Math.round(oa * 255);
  };
  const cover = (d: number): number => Math.max(0, Math.min(1, 0.5 - d));
  return {
    put,
    grad(top, bottom) {
      for (let y = 0; y < S; y++) {
        const c = mix(top, bottom, y / (S - 1));
        for (let x = 0; x < S; x++) put(x, y, c, 1);
      }
    },
    circle(cx, cy, r, c, a = 1) {
      for (let y = Math.floor(cy - r - 1); y <= cy + r + 1; y++) {
        for (let x = Math.floor(cx - r - 1); x <= cx + r + 1; x++) {
          const d = Math.hypot(x + 0.5 - cx, y + 0.5 - cy) - r;
          put(x, y, c, cover(d) * a);
        }
      }
    },
    ring(cx, cy, r, w, c, a = 1) {
      for (let y = Math.floor(cy - r - w - 1); y <= cy + r + w + 1; y++) {
        for (let x = Math.floor(cx - r - w - 1); x <= cx + r + w + 1; x++) {
          const d = Math.abs(Math.hypot(x + 0.5 - cx, y + 0.5 - cy) - r) - w / 2;
          put(x, y, c, cover(d) * a);
        }
      }
    },
    rrect(x0, y0, x1, y1, r, c, a = 1) {
      const hx = (x1 - x0) / 2;
      const hy = (y1 - y0) / 2;
      const mx = x0 + hx;
      const my = y0 + hy;
      for (let y = Math.floor(y0 - 1); y <= y1 + 1; y++) {
        for (let x = Math.floor(x0 - 1); x <= x1 + 1; x++) {
          const qx = Math.abs(x + 0.5 - mx) - hx + r;
          const qy = Math.abs(y + 0.5 - my) - hy + r;
          const d = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - r;
          put(x, y, c, cover(d) * a);
        }
      }
    },
    clear() {
      for (let i = 0; i < S * S * 4; i++) buf[base + i] = 0;
    }
  };
}

// ---- Palette: docs/08 tokens softened toward paper-50 (#FFF9EE) for the warm pastel toy look.
const PAPER = hex(0xfff9ee);
const soft = (h: number, t = 0.22): RGB => mix(hex(h), PAPER, t);
const C = {
  leaf: soft(0x3dbe6b, 0.18),
  leafLight: soft(0x3dbe6b, 0.42),
  leafDeep: soft(0x1b7a3e, 0.25),
  clay: soft(0xc98b4a, 0.25),
  clayDeep: soft(0x8a5a2b, 0.3),
  stone: soft(0x8fa0b8, 0.2),
  stoneDeep: soft(0x5f6778, 0.3),
  coral: soft(0xff6b4a, 0.18),
  coralDeep: soft(0xc73e22, 0.2),
  honey: soft(0xe8a53a, 0.2),
  honeyDeep: soft(0xb7792a, 0.2),
  cream: hex(0xf4ebdd),
  sky: soft(0x3fa9f5, 0.25),
  skyDeep: soft(0x1b6fb8, 0.2),
  sun: soft(0xffc53d, 0.1),
  grape: soft(0x8e5be8, 0.2),
  ink: hex(0x3a4152),
  white: hex(0xffffff),
  slate: soft(0x5a6578, 0.18),
  sand: soft(0xe8c27a, 0.2),
  wood: soft(0xc98b4a, 0.12),
  woodLight: soft(0xe0b07a, 0.15),
  woodDark: soft(0x7a5236, 0.15)
};

/** Flat pastel with the top-light gradient every tile shares (docs/08 6.1 '윗면을 한 단계 밝게'). */
function base(p: Painter, c: RGB, lift = 0.07): void {
  p.grad(shade(c, 1 + lift), shade(c, 1 - lift));
}

/** Two wide boards with a rounded groove and one soft knot — toy wood, not staggered planks. */
function boards(p: Painter, seed: number, c: RGB): void {
  base(p, c, 0.05);
  for (const y0 of [0, 16]) {
    p.rrect(1, y0 + 1, 31, y0 + 15, 3, shade(c, 1.06));
    p.rrect(1, y0 + 13.5, 31, y0 + 15, 1, shade(c, 0.9), 0.7);
  }
  const kx = 6 + Math.floor(hash2(seed, 1, 1) * 20);
  p.ring(kx, 8, 2.2, 1, shade(c, 0.86), 0.55);
  p.ring(31 - kx, 24, 1.8, 1, shade(c, 0.86), 0.5);
}

/** Felt: flat color, dashed stitch border inset like a sewn toy. */
function felt(p: Painter, c: RGB): void {
  base(p, c, 0.04);
  const st = shade(c, 1.22);
  for (let i = 4; i < 28; i += 4) {
    for (const [x, y] of [[i, 3], [i, 28], [3, i], [28, i]] as const) p.rrect(x, y, x + 2, y + 1, 0.5, st, 0.9);
  }
}

/** Fish-scale shingles: rows of half circles, offset each row. */
function shingles(p: Painter, c: RGB): void {
  base(p, shade(c, 0.9), 0.04);
  for (let row = 0; row < 5; row++) {
    const y = row * 8 - 2;
    const off = row % 2 === 0 ? 0 : 4;
    for (let x = -4 + off; x < 36; x += 8) {
      p.circle(x + 4, y + 4, 4.6, shade(c, 0.86));
      p.circle(x + 4, y + 3.4, 4.0, shade(c, 1.04 - row * 0.01));
    }
  }
}

/** Big rounded bricks (two courses per tile). */
function bigBricks(p: Painter, c: RGB, mortar: RGB, courses = 2): void {
  base(p, mortar, 0.03);
  const h = S / courses;
  for (let r = 0; r < courses; r++) {
    const off = r % 2 === 0 ? 0 : S / 4;
    for (let x = -S / 2 + off; x < S; x += S / 2) {
      p.rrect(x + 1.5, r * h + 1.5, x + S / 2 - 1.5, r * h + h - 1.5, 3, shade(c, 1.0 - r * 0.03));
      p.rrect(x + 3, r * h + 2.5, x + S / 2 - 6, r * h + 4.5, 1, shade(c, 1.12), 0.6);
    }
  }
}

/** Rounded pebbles packed on a base. */
function pebbles(p: Painter, seed: number, bg: RGB, cs: readonly RGB[], n = 9, rMin = 3, rMax = 6): void {
  base(p, bg, 0.04);
  for (let i = 0; i < n; i++) {
    const x = hash2(seed, i, 1) * S;
    const y = hash2(seed, i, 2) * S;
    const r = rMin + hash2(seed, i, 3) * (rMax - rMin);
    const c = cs[i % cs.length]!;
    for (const dx of [-S, 0, S]) for (const dy of [-S, 0, S]) {
      p.circle(x + dx, y + dy + 0.6, r, shade(c, 0.85), 0.8);
      p.circle(x + dx, y + dy, r - 0.4, c);
      p.circle(x + dx - r * 0.3, y + dy - r * 0.35, r * 0.35, shade(c, 1.12), 0.6);
    }
  }
}

/** Flower cross-quad texture: stem + round petals (cutout). */
function flower(p: Painter, petal: RGB, center: RGB): void {
  p.clear();
  p.rrect(15, 14, 17, 32, 1, C.leafDeep);
  p.circle(11, 22, 3.5, C.leaf);
  p.circle(21, 25, 3, C.leaf);
  for (let k = 0; k < 5; k++) {
    const a = (k / 5) * Math.PI * 2 - Math.PI / 2;
    p.circle(16 + Math.cos(a) * 5, 10 + Math.sin(a) * 5, 4, petal);
  }
  p.circle(16, 10, 3, center);
}

const PAINT: Record<TileName, (p: Painter, seed: number) => void> = {
  grass_top: (p, s) => {
    base(p, C.leaf, 0.03);
    for (let i = 0; i < 6; i++) p.circle(hash2(s, i, 1) * S, hash2(s, i, 2) * S, 5 + hash2(s, i, 3) * 4, C.leafLight, 0.22);
    for (let i = 0; i < 3; i++) {
      const x = 4 + hash2(s, i, 5) * 24;
      const y = 4 + hash2(s, i, 6) * 24;
      for (const [dx, dy] of [[-1.2, 0], [1.2, 0], [0, -1.2]] as const) p.circle(x + dx, y + dy, 1.3, C.leafLight, 0.8);
    }
  },
  grass_side: (p) => {
    base(p, C.clay, 0.05);
    // a rounded "frosting" cap with scalloped edge — the toy-cake grass, not a jagged fringe
    p.rrect(-2, -2, 34, 9, 0, C.leaf);
    for (let x = 0; x < S; x += 8) p.circle(x + 4, 9, 4, C.leaf);
    p.rrect(-2, -2, 34, 2.5, 0, C.leafLight, 0.6);
    p.circle(8, 22, 1.6, C.clayDeep, 0.5);
    p.circle(23, 26, 2, C.clayDeep, 0.45);
  },
  dirt: (p, s) => pebbles(p, s, C.clay, [shade(C.clay, 0.9), shade(C.clay, 1.08)], 6, 2, 4),
  stone: (p, s) => pebbles(p, s, shade(C.stone, 0.92), [C.stone, shade(C.stone, 1.06), shade(C.stone, 0.96)], 7, 5, 8),
  brick: (p) => bigBricks(p, C.coral, C.cream),
  road: (p) => {
    base(p, C.slate, 0.02);
    p.rrect(1, 1, 31, 31, 4, shade(C.slate, 1.06));
    p.rrect(1, 1, 31, 31, 4, shade(C.slate, 0.92), 0.0);
  },
  bedrock: (p, s) => pebbles(p, s, hex(0x2f3546), [hex(0x3a4152), hex(0x454d60)], 8, 4, 7),
  dynamite_side: (p) => {
    base(p, C.coral, 0.05);
    p.rrect(0, 12, 32, 20, 0, C.cream);
    p.rrect(0, 14.5, 32, 17.5, 0, C.ink, 0.25);
  },
  dynamite_top: (p) => {
    base(p, C.coral, 0.03);
    p.circle(16, 16, 5, C.cream);
    p.circle(16, 16, 2, C.ink);
  },
  plank: (p, s) => boards(p, s, C.wood),
  glass: (p) => {
    p.clear();
    p.rrect(0, 0, 32, 32, 0, C.sky, 0.28);
    p.rrect(1, 1, 31, 31, 4, C.white, 0.0);
    for (let k = 0; k < 2; k++) {
      for (let i = 0; i < 9; i++) p.circle(6 + i + k * 9, 20 - i + k * 2, 1.1, C.white, 0.75);
    }
    // soft rounded frame
    for (let i = 0; i < S; i++) {
      for (const [x, y] of [[i, 0], [i, 31], [0, i], [31, i]] as const) p.put(x, y, C.white, 0.7);
    }
  },
  vault: (p) => {
    base(p, C.slate, 0.04);
    p.ring(16, 16, 8, 2.5, C.sun);
    p.circle(16, 16, 3, C.sun);
  },
  sand: (p, s) => {
    base(p, C.sand, 0.04);
    for (let i = 0; i < 10; i++) p.circle(hash2(s, i, 1) * S, hash2(s, i, 2) * S, 1, shade(C.sand, 1.1), 0.7);
  },
  gravel: (p, s) => pebbles(p, s, soft(0x9a948c), [soft(0xb2aaa1), soft(0x857e78), soft(0xa29a92)], 14, 2, 4),
  snow: (p) => base(p, hex(0xf6fafd), 0.03),
  granite: (p, s) => pebbles(p, s, soft(0xc49482, 0.15), [soft(0xa87766, 0.1), soft(0xd6a796, 0.1)], 8, 3, 6),
  marble: (p, s) => {
    base(p, hex(0xf7f3ec), 0.03);
    for (let i = 0; i < 2; i++) {
      const y0 = 6 + hash2(s, i, 1) * 20;
      for (let x = 0; x < S; x++) p.circle(x, y0 + Math.sin(x / 5 + i) * 3, 0.8, soft(0xb9a2f5, 0.4), 0.5);
    }
  },
  oak_plank: (p, s) => boards(p, s, C.wood),
  birch_plank: (p, s) => boards(p, s, soft(0xead2a0, 0.1)),
  pine_plank: (p, s) => boards(p, s, soft(0x9a6a45, 0.1)),
  log_side: (p) => {
    base(p, C.woodDark, 0.04);
    for (let x = 2; x < S; x += 7) p.rrect(x, -2, x + 3.5, 34, 1.75, shade(C.woodDark, 1.12), 0.8);
  },
  log_top: (p) => {
    base(p, C.woodLight, 0.02);
    p.ring(16, 16, 14, 3, C.woodDark);
    p.ring(16, 16, 9, 1.2, shade(C.woodLight, 0.88));
    p.ring(16, 16, 4.5, 1.2, shade(C.woodLight, 0.88));
  },
  door: (p) => {
    base(p, C.honey, 0.05);
    p.rrect(4, 3, 28, 29, 4, shade(C.honey, 1.08));
    p.rrect(7, 6, 25, 14, 3, C.sky, 0.85);
    p.circle(22, 19, 1.8, C.sun);
  },
  ladder: (p) => {
    p.clear();
    p.rrect(5, 0, 9, 32, 1.5, C.wood);
    p.rrect(23, 0, 27, 32, 1.5, C.wood);
    for (let y = 4; y < S; y += 8) p.rrect(5, y, 27, y + 3, 1.5, C.woodLight);
  },
  stained_glass: (p) => {
    p.clear();
    const cols = [C.coral, C.sun, C.sky, C.leaf];
    for (let i = 0; i < 4; i++) p.rrect((i % 2) * 16 + 1, Math.floor(i / 2) * 16 + 1, (i % 2) * 16 + 15, Math.floor(i / 2) * 16 + 15, 4, cols[i]!, 0.6);
  },
  torch: (p) => {
    p.clear();
    p.rrect(14, 12, 18, 32, 1.5, C.wood);
    p.circle(16, 10, 4.5, C.sun);
    p.circle(16, 9, 2.5, C.white, 0.9);
  },
  lantern: (p) => {
    base(p, C.sun, 0.06);
    p.rrect(3, 3, 29, 29, 5, shade(C.sun, 1.15));
    p.rrect(0, 0, 32, 4, 0, C.woodDark);
    p.rrect(0, 28, 32, 32, 0, C.woodDark);
  },
  neon: (p) => {
    base(p, hex(0x1c1b3a), 0.02);
    p.ring(16, 16, 9, 2.5, soft(0xff4fa3, 0.1));
  },
  iron_plate: (p) => {
    base(p, soft(0xc9ced9, 0.1), 0.06);
    for (const [x, y] of [[5, 5], [27, 5], [5, 27], [27, 27]] as const) p.circle(x, y, 1.6, shade(soft(0xc9ced9, 0.1), 0.85));
  },
  copper: (p) => {
    base(p, soft(0xd48955, 0.1), 0.07);
    p.rrect(4, 4, 28, 28, 5, soft(0xe09a66, 0.15), 0.7);
  },
  gold_trim: (p) => {
    base(p, C.sun, 0.08);
    p.rrect(0, 12, 32, 20, 0, shade(C.sun, 1.12));
  },
  iron_bars: (p) => {
    p.clear();
    for (let x = 3; x < S; x += 8) p.rrect(x, 0, x + 3, 32, 1.5, soft(0x7c8796, 0.1));
  },
  roof_red: (p) => shingles(p, C.coral),
  roof_blue: (p) => shingles(p, C.sky),
  roof_slate: (p) => shingles(p, soft(0x6a7488, 0.12)),
  thatch: (p) => {
    base(p, soft(0xe2c46a, 0.1), 0.05);
    for (let row = 0; row < 4; row++) {
      for (let x = -2; x < S + 2; x += 4) p.rrect(x, row * 8 + 1, x + 3, row * 8 + 9, 1.5, shade(soft(0xe2c46a, 0.1), 0.94 + (x % 8 === 0 ? 0.08 : 0)), 0.9);
    }
  },
  sandstone: (p) => {
    base(p, C.sand, 0.05);
    p.rrect(0, 10, 32, 12, 0, shade(C.sand, 0.9), 0.6);
    p.rrect(0, 22, 32, 24, 0, shade(C.sand, 0.9), 0.6);
  },
  ice_brick: (p) => bigBricks(p, soft(0x9fd3f0, 0.2), hex(0xe8f6fd)),
  bamboo: (p) => {
    base(p, soft(0x7ac74f, 0.15), 0.04);
    for (let x = 1; x < S; x += 8) {
      p.rrect(x, -1, x + 6, 33, 3, soft(0x7ac74f, 0.25));
      p.rrect(x, 15, x + 6, 17, 1, soft(0x2e8b4f, 0.2));
    }
  },
  station_panel: (p) => {
    base(p, soft(0xc7d0e0, 0.1), 0.05);
    p.rrect(3, 3, 29, 29, 4, soft(0xdbe2ee, 0.1));
    p.circle(25, 7, 1.6, soft(0x6fe3ff, 0.1));
  },
  scaffold: (p) => {
    p.clear();
    p.rrect(1, 1, 31, 4, 1.5, C.woodLight);
    p.rrect(1, 28, 31, 31, 1.5, C.woodLight);
    p.rrect(1, 1, 4, 31, 1.5, C.woodLight);
    p.rrect(28, 1, 31, 31, 1.5, C.woodLight);
    for (let i = 0; i < 26; i++) p.circle(3 + i, 3 + i, 1.3, C.wood);
  },
  nameplate: (p) => {
    // speech-bubble sign: LCW's own signage motif
    base(p, C.woodLight, 0.04);
    p.rrect(3, 5, 29, 21, 6, C.white);
    p.circle(10, 23, 3.5, C.white);
    p.circle(7, 27, 1.8, C.white);
    for (let x = 9; x < 24; x += 5) p.circle(x, 13, 1.6, C.ink, 0.8);
  },
  carpet: (p) => felt(p, C.coral),
  flower_pot: (p) => {
    base(p, soft(0xd27a55, 0.15), 0.06);
    p.rrect(0, 0, 32, 6, 0, soft(0xe0906a, 0.2));
    p.circle(16, 18, 3, C.cream, 0.6);
  },
  leaves: (p, s) => {
    p.clear();
    for (let i = 0; i < 12; i++) {
      const x = hash2(s, i, 1) * S;
      const y = hash2(s, i, 2) * S;
      const r = 5 + hash2(s, i, 3) * 3;
      for (const dx of [-S, 0, S]) for (const dy of [-S, 0, S]) {
        p.circle(x + dx, y + dy + 0.8, r, C.leafDeep);
        p.circle(x + dx, y + dy, r - 0.5, i % 3 === 0 ? C.leafLight : C.leaf);
      }
    }
  },
  water: (p) => {
    base(p, C.sky, 0.04);
    for (let y = 6; y < S; y += 10) for (let x = 0; x < S; x++) p.circle(x, y + Math.sin(x / 3) * 1.4, 0.7, C.white, 0.35);
  },
  flower_red: (p) => flower(p, C.coral, C.sun),
  flower_yellow: (p) => flower(p, C.sun, soft(0xff8a3d, 0.1)),
  flower_blue: (p) => flower(p, C.sky, C.white),
  tall_grass: (p) => {
    p.clear();
    for (const [x, h, w] of [[6, 18, 3], [12, 26, 3.5], [18, 22, 3], [24, 16, 3], [27, 24, 2.5]] as const) {
      p.rrect(x - w / 2, S - h, x + w / 2, S + 2, w / 2, x % 2 === 0 ? C.leaf : C.leafLight);
    }
  },
  honeycomb: (p) => {
    base(p, C.honey, 0.05);
    for (let row = 0; row < 4; row++) {
      for (let x = row % 2 === 0 ? 4 : 8; x < S + 4; x += 8) {
        p.circle(x, row * 8 + 4, 3.6, shade(C.honey, 1.14));
        p.circle(x - 1, row * 8 + 3, 1.2, C.white, 0.5);
      }
    }
  },
  wool_white: (p) => felt(p, hex(0xfbf6ec)),
  wool_red: (p) => felt(p, C.coral),
  wool_yellow: (p) => felt(p, C.sun),
  wool_blue: (p) => felt(p, C.sky),
  wool_green: (p) => felt(p, C.leaf),
  wool_orange: (p) => felt(p, soft(0xff8a3d, 0.12)),
  crate: (p) => {
    base(p, C.woodLight, 0.04);
    p.rrect(2, 2, 30, 30, 4, shade(C.woodLight, 1.05));
    for (let i = 0; i < 22; i++) p.circle(6 + i, 26 - i, 1.8, C.wood);
    p.ring(16, 16, 15, 2.2, C.wood, 0.0);
    for (const [x, y] of [[0, 0], [28, 0], [0, 28], [28, 28]] as const) p.rrect(x, y, x + 4, y + 4, 1.5, C.wood);
  },
  barrel_side: (p) => {
    base(p, C.wood, 0.05);
    for (let x = 0; x < S; x += 8) p.rrect(x + 0.5, -1, x + 7.5, 33, 3, shade(C.wood, 1.06));
    p.rrect(0, 6, 32, 9, 0, C.slate);
    p.rrect(0, 23, 32, 26, 0, C.slate);
  },
  barrel_top: (p) => {
    base(p, C.woodLight, 0.02);
    p.ring(16, 16, 14, 3, C.slate);
  },
  hay_side: (p) => {
    base(p, soft(0xe5c45a, 0.12), 0.05);
    for (let x = 1; x < S; x += 3) p.rrect(x, 1, x + 1.6, 31, 0.8, soft(0xf0d26a, 0.2), 0.7);
    p.rrect(0, 13, 32, 17, 0, soft(0xc98b4a, 0.2));
  },
  hay_top: (p) => {
    base(p, soft(0xe5c45a, 0.12), 0.03);
    p.ring(16, 16, 9, 2, soft(0xc9a640, 0.15), 0.6);
  },
  cobblestone: (p, s) => pebbles(p, s, shade(C.stone, 0.85), [C.stone, shade(C.stone, 1.08), soft(0xa7b4c6, 0.2)], 11, 4, 6),
  jar_shelf: (p) => {
    // LCW honey-cafe display shelf: one open cubby on a cream polka-dot wall, a single thick board with brackets, and
    // two different things standing on it - a big round honey jar under a coral cloth cap and a sky mug with steam.
    // One board and two unlike objects per block, so a row reads as a cafe display, never as rows of thin spines.
    const wall = mix(C.cream, PAPER, 0.35);
    base(p, wall, 0.02);
    for (let y = 3; y < 22; y += 6) for (let x = (y % 12 === 3 ? 2 : 5); x < 32; x += 6) p.circle(x, y, 0.9, C.honey, 0.35);
    p.rrect(0, 0, 32, 2.5, 0, C.woodLight); // top trim
    // board, its shadow on the wall and two little brackets
    p.rrect(0, 21, 32, 26, 1.5, C.wood);
    p.rrect(0, 21, 32, 22.2, 0, shade(C.wood, 1.18));
    p.rrect(0, 26, 32, 27.5, 0, shade(wall, 0.82));
    for (const x of [4, 27]) p.rrect(x, 26, x + 2, 30, 1, C.woodDark);
    p.rrect(0, 30, 32, 32, 0, C.woodLight); // bottom trim
    // honey jar: round body, shine, label with a tiny bee dot, cloth cap tied with a string
    p.rrect(3, 10, 16, 21.5, 5, C.honey);
    p.rrect(4.5, 11.5, 7, 17, 1.2, shade(C.honey, 1.25), 0.8);
    p.circle(10.2, 16.2, 3.1, PAPER);
    p.circle(10.2, 16.2, 1.3, C.honeyDeep);
    p.rrect(2, 6.5, 17, 10.5, 2, C.coral);
    for (const x of [4.5, 8.5, 12.5]) p.circle(x, 8.5, 0.9, PAPER, 0.85);
    p.rrect(3.5, 10, 15.5, 11, 0, C.coralDeep);
    // mug with a handle and two puffs of steam
    p.rrect(19.5, 14.5, 26.5, 21.5, 2, C.sky);
    p.rrect(20.5, 15.5, 22, 20, 0.8, shade(C.sky, 1.3), 0.7);
    p.ring(27.6, 18, 2, 1.4, C.sky);
    p.circle(22.5, 11, 1.5, PAPER, 0.75);
    p.circle(24, 7.8, 1.2, PAPER, 0.6);
  },
  dark_plank: (p, s) => boards(p, s, C.woodDark),
  chest_side: (p) => {
    base(p, C.wood, 0.05);
    p.rrect(1, 1, 31, 31, 5, shade(C.wood, 1.06));
    p.rrect(0, 11, 32, 15, 0, C.sun);
    p.rrect(13, 9, 19, 19, 2, C.sun);
    p.circle(16, 15, 1.4, C.ink);
  },
  chest_top: (p) => {
    base(p, C.wood, 0.03);
    p.rrect(2, 2, 30, 30, 5, shade(C.wood, 1.08));
    p.rrect(13, 0, 19, 32, 0, C.sun);
  },
  path_top: (p, s) => {
    base(p, soft(0xd8c39a, 0.2), 0.02);
    for (let i = 0; i < 4; i++) {
      const x = 8 + (i % 2) * 16 + (hash2(s, i, 1) - 0.5) * 4;
      const y = 8 + Math.floor(i / 2) * 16 + (hash2(s, i, 2) - 0.5) * 4;
      p.circle(x, y + 0.7, 6, soft(0xb69566, 0.25), 0.8);
      p.circle(x, y, 5.6, soft(0xe9dcc3, 0.2));
    }
  },
  wool_pink: (p) => felt(p, soft(0xff9cc2, 0.1)),
  wool_purple: (p) => felt(p, C.grape),
  terracotta_honey: (p) => {
    base(p, soft(0xe39834, 0.12), 0.06);
    p.rrect(0, 12, 32, 20, 0, shade(soft(0xe39834, 0.12), 1.1));
  },
  chalkboard: (p) => {
    // notice board: green board in a honey frame with a chalk speech bubble
    base(p, C.honeyDeep, 0.04);
    p.rrect(2, 2, 30, 30, 2, soft(0x2e6b4f, 0.1));
    p.rrect(7, 7, 25, 19, 5, C.white, 0.0);
    for (let a = 0; a < 40; a++) {
      const t = (a / 40) * Math.PI * 2;
      p.circle(16 + Math.cos(t) * 8, 13 + Math.sin(t) * 5, 0.7, C.white, 0.85);
    }
    p.circle(11, 20, 1, C.white, 0.85);
    p.circle(9, 22.5, 0.8, C.white, 0.85);
  },
  stone_brick: (p) => bigBricks(p, soft(0xd8cbb6, 0.1), soft(0xb7a68c, 0.15), 2)
};

/** Shader bevel strength per tile (materials.ts): 1 = full toy bevel, lower on ground so roads stay calm. */
const CALM: ReadonlySet<TileName> = new Set<TileName>(['grass_top', 'path_top', 'road', 'sand', 'snow', 'gravel', 'dirt', 'grass_side', 'water']);
const NONE: ReadonlySet<TileName> = new Set<TileName>([
  'glass', 'stained_glass', 'leaves', 'flower_red', 'flower_yellow', 'flower_blue', 'tall_grass', 'torch', 'ladder', 'iron_bars', 'scaffold'
]);
export function tileBevel(name: TileName): number {
  return NONE.has(name) ? 0 : CALM.has(name) ? 0.35 : 1;
}

/** RGBA texels for all tiles, layer-major: layer i occupies [i*S*S*4, (i+1)*S*S*4). */
export function buildAtlasPixels(): Uint8Array<ArrayBuffer> {
  const layerBytes = S * S * 4;
  const buf = new Uint8Array(layerBytes * TILE_NAMES.length);
  TILE_NAMES.forEach((name, i) => {
    const p = makePainter(buf, i * layerBytes);
    PAINT[name](p, i * 31 + 7);
  });
  return buf;
}

/** Average color of a tile (for particles, debris, icons). */
export function tileAverageColor(pixels: Uint8Array, layer: number): [number, number, number] {
  const layerBytes = S * S * 4;
  let r = 0;
  let g = 0;
  let b = 0;
  let n = 0;
  for (let i = layer * layerBytes; i < (layer + 1) * layerBytes; i += 4) {
    if (pixels[i + 3]! < 128) continue;
    r += pixels[i]!;
    g += pixels[i + 1]!;
    b += pixels[i + 2]!;
    n++;
  }
  if (n === 0) return [1, 1, 1];
  return [r / n / 255, g / n / 255, b / n / 255];
}
